local byID,byNPC=ns.AthenaLoreBuildIndex.Get(true)
for _,row in ipairs(rows) do
 local e=byID[row.id]
 if row.existing then assert(e and e.kind==row.kind,"Changed existing reference target")
 else
  assert(not e,"Duplicate basic reference subject")
  for _,id in ipairs(row.npcIDs or {}) do assert(not byNPC[id],"Duplicate canonical unit address") end
  e={id=row.id,title=row.title,kind=row.kind,fields={},aliases={row.title},related={},
   npcIDs=row.npcIDs,gate='DISCOVERY',sourceURL=row.sourceURL,sourceVersion=row.sourceVersion,
   referenceStatus=row.referenceStatus,catalogReferenceOnly=true,journalFields={}}
  D.entries[#D.entries+1]=e;byID[e.id]=e;for _,id in ipairs(e.npcIDs or {}) do byNPC[id]=e end
 end
 e.catalogReferenceMetadata=row.catalogMetadata
 if not row.existing then
  local aliases={};for _,name in ipairs(e.aliases or {}) do aliases[name]=true end
  for _,name in ipairs(row.searchAliases or {}) do if not aliases[name] then e.aliases[#e.aliases+1]=name;aliases[name]=true end end
 end
 e.sourceIdentifiers=e.sourceIdentifiers or {}
 for _,candidate in ipairs(row.sourceIdentifiers) do
  local seen=false;for _,old in ipairs(e.sourceIdentifiers) do if old.namespace==candidate.namespace and old.id==candidate.id then seen=true;break end end
  if not seen then e.sourceIdentifiers[#e.sourceIdentifiers+1]=candidate end
 end
 e.fieldSources=e.fieldSources or {};e.fieldVersions=e.fieldVersions or {}
 if not row.existing and not row.skipFieldEnrichment then for field,text in pairs(row.fields) do
  if not e.fields[field] or e.fields[field]=='UNKNOWN' then
   e.fields[field]=text;e.fieldSources[field]=row.fieldSources and row.fieldSources[field] or row.sourceURL;e.fieldVersions[field]=row.sourceVersion
  end
 end end
